# Generated by GPT-6.2 Astra
import argparse
import hashlib
import json
from collections import defaultdict
from pathlib import Path
from statistics import median

from character_model import MODEL56, ROOT


def main():
    ap = argparse.ArgumentParser(
        description="Summarize independently re-presented physical cards saved in the serial viewer."
    )
    ap.add_argument("--captures", type=Path, default=ROOT / "captures")
    ap.add_argument(
        "--out", type=Path, default=ROOT / "release" / MODEL56.name / "实拍验收.md"
    )
    args = ap.parse_args()
    fingerprint = hashlib.sha256(
        (MODEL56 / "integer_model.npz").read_bytes()
    ).hexdigest()
    classes = json.loads((MODEL56 / "classes.json").read_text("utf8"))
    seen = {
        r["source_group"]
        for r in json.loads((MODEL56 / "splits.json").read_text("utf8"))
        if r["split"] != "test"
    }
    demo = defaultdict(list)
    novelty = []
    fps = []
    keys = set()
    for path in sorted(args.captures.rglob("*.json")):
        r = json.loads(path.read_text("utf8"))
        if (
            r.get("format") != "NPU4-RGB565-LE"
            or r.get("origin") != "fpga"
            or r.get("model_sha256") != fingerprint
        ):
            continue
        if r["split"] not in ("test", "demo"):
            continue
        if r.get("subject_origin") != "actual" or r.get("label") not in range(1, 16):
            continue
        key = (r["session"], r["sequence"])
        if key in keys:
            continue
        keys.add(key)
        reported = r["wire_id"] + 1 if r["status"] == 1 else 0
        correct = r["status"] != 2 and reported == r["label"]
        if r["split"] == "demo":
            demo[r["label"]].append(correct)
        elif r["source_group"] not in seen:
            novelty.append((r["source_group"], r["label"], reported, r["status"]))
        if r.get("received_fps") is not None:
            fps.append(r["received_fps"])
    count = sum(map(len, demo.values()))
    lines = [
        "# OV2640 实拍验收",
        "",
        f"当前模型有 {count} 次独立复摆记录、{len(novelty)} 次留出作品拍摄记录。"
        + ("目前尚无板卡实拍数据。" if not count and not novelty else ""),
        "",
        "用同一套 Nexys A7、OV2640 和 USB 线，将当前 bitstream 下载到板上并连接 460800 串口。"
        "先出示红、绿、蓝卡与带上箭头的图案，核对通道、方向及中央取景。每次把目标完全移开、重新摆放并等到新帧后，"
        "点“保存当前样本”，填写实际角色、原作品组和场次，画面来源选“真实作品或实物”。现场复摆选 demo，新作品抽测选 test。"
        "只计当前模型的真实 FPGA 串口帧，同一场次与序号只算一次。",
        "",
        "| 角色 | 已录 / 计划 | 首五次正确 | 目标 |",
        "|---|---:|---:|---:|",
    ]
    for c in classes:
        results = demo[c["class_id"]]
        lines.append(
            f"| {c['class_id']:02d} {c['name']} | {len(results)} / 5 | {sum(results[:5]) if results else '—'} | ≥4 |"
        )
    lines += [
        "",
        f"接收帧率中位数为 {format(median(fps),'.2f')+' 帧/秒' if fps else '待测'}，现场目标至少 3 帧/秒。",
        "",
        "## 留出作品实拍",
        "",
    ]
    if novelty:
        lines += ["| 来源组 | 真实编号 | 报告编号 | 状态 |", "|---|---:|---:|---:|"]
        lines.extend(
            f"| {g} | {label} | {pred} | {status} |"
            for g, label, pred, status in novelty
        )
    else:
        lines.append("待测。每类至少展示一件训练和验证中均未见的作品。")
    args.out.parent.mkdir(parents=True, exist_ok=True)
    args.out.write_text("\n".join(lines) + "\n", encoding="utf8")
    print(args.out)


if __name__ == "__main__":
    main()
